def get_optimal_action(player_score, dealer_upcard, usable_ace=False):
    key = (player_score, dealer_upcard, usable_ace)
    return BASIC_STRATEGY.get(key, "stand")


def generate_training_data(num_samples=500000, seed=42):
    import random
    random.seed(seed)

    states = []
    labels = []

    for _ in range(num_samples):
        player_score = random.randint(4, 20)
        dealer_card = random.randint(2, 11)
        usable_ace = random.choice([True, False])
        true_count = random.randint(-5, 10)

        action = get_optimal_action(player_score, dealer_card, usable_ace)
        action_idx = 0 if action == "hit" else 1

        states.append([player_score, dealer_card, int(usable_ace), true_count])
        labels.append(action_idx)

    return states, labels